#!/usr/bin/env python3
"""Fail when raster images are tracked outside the explicit allowlist."""
import pathlib
import subprocess
import sys

ROOT = pathlib.Path(__file__).resolve().parents[2]
RASTER = (".png", ".jpg", ".jpeg", ".gif", ".webp")
# Visual regression baselines for the browser suite, required by AGENTS.md for every UI change.
# The documentation screenshots are generated by tests/browser/specs/docs-screenshots.spec.ts; no other raster
# image may be tracked, so a screenshot is never added or edited by hand.
SNAPSHOT_DIRS = (
    "tests/browser/specs/__snapshots__/",
    "tests/browser/fleet-specs/__snapshots__/",
)
GENERATED_DIRS = ("docs/public/screenshots/",)
RELEASE_MARKER = ROOT / "docs/public/screenshots/release.txt"


def main() -> int:
    tracked = subprocess.check_output(["git", "ls-files"], cwd=ROOT, text=True).splitlines()
    offenders = [
        p for p in tracked
        if p.lower().endswith(RASTER) and not p.startswith(SNAPSHOT_DIRS + GENERATED_DIRS)
    ]
    for path in offenders:
        print(f"tracked raster image: {path}")
    stale = False
    if any(p.startswith(GENERATED_DIRS) for p in tracked):
        version = (ROOT / "VERSION").read_text(encoding="utf-8").strip()
        recorded = RELEASE_MARKER.read_text(encoding="utf-8").strip() if RELEASE_MARKER.is_file() else ""
        if recorded != version:
            print(f"documentation screenshots are for release {recorded or 'unknown'}, not {version}; regenerate them")
            stale = True
    return 1 if offenders or stale else 0


if __name__ == "__main__":
    sys.exit(main())
